/*
 * TI driver instances used by the BLE5-Stack, normally generated by
 * SysConfig (ti_drivers_config.c). Interrupt priorities follow the
 * SysConfig defaults.
 */

#include <stdint.h>

#include "ti_drivers_config.h"

#include <ti/drivers/AESCCM.h>
#include <ti/drivers/aesccm/AESCCMCC26XX.h>
#include <ti/drivers/AESECB.h>
#include <ti/drivers/aesecb/AESECBCC26XX.h>
#include <ti/drivers/AESCTRDRBG.h>
#include <ti/drivers/aesctrdrbg/AESCTRDRBGXX.h>
#include <ti/drivers/ECDH.h>
#include <ti/drivers/ecdh/ECDHCC26X2.h>
#include <ti/drivers/TRNG.h>
#include <ti/drivers/trng/TRNGCC26XX.h>

/* (~0) selects the lowest interrupt priority */
#define TI_BLE_CRYPTO_INT_PRIORITY (~0)

static AESCCMCC26XX_Object aesccmObjects[CONFIG_TI_DRIVERS_AESCCM_COUNT];
static const AESCCMCC26XX_HWAttrs aesccmHWAttrs[CONFIG_TI_DRIVERS_AESCCM_COUNT] = {
	{
		.intPriority = TI_BLE_CRYPTO_INT_PRIORITY,
	},
};
const AESCCM_Config AESCCM_config[CONFIG_TI_DRIVERS_AESCCM_COUNT] = {
	{
		.object = &aesccmObjects[CONFIG_AESCCM_0],
		.hwAttrs = &aesccmHWAttrs[CONFIG_AESCCM_0],
	},
};
const uint_least8_t AESCCM_count = CONFIG_TI_DRIVERS_AESCCM_COUNT;

static AESECBCC26XX_Object aesecbObjects[CONFIG_TI_DRIVERS_AESECB_COUNT];
static const AESECBCC26XX_HWAttrs aesecbHWAttrs[CONFIG_TI_DRIVERS_AESECB_COUNT] = {
	{
		.intPriority = TI_BLE_CRYPTO_INT_PRIORITY,
	},
};
const AESECB_Config AESECB_config[CONFIG_TI_DRIVERS_AESECB_COUNT] = {
	{
		.object = &aesecbObjects[CONFIG_AESECB_0],
		.hwAttrs = &aesecbHWAttrs[CONFIG_AESECB_0],
	},
};
const uint_least8_t AESECB_count = CONFIG_TI_DRIVERS_AESECB_COUNT;

static AESCTRDRBGXX_Object aesctrdrbgObjects[CONFIG_TI_DRIVERS_AESCTRDRBG_COUNT];
static const AESCTRDRBGXX_HWAttrs aesctrdrbgHWAttrs[CONFIG_TI_DRIVERS_AESCTRDRBG_COUNT] = {
	{
		.aesctrHWAttrs.intPriority = TI_BLE_CRYPTO_INT_PRIORITY,
	},
};
const AESCTRDRBG_Config AESCTRDRBG_config[CONFIG_TI_DRIVERS_AESCTRDRBG_COUNT] = {
	{
		.object = &aesctrdrbgObjects[CONFIG_AESCTRDRBG_0],
		.hwAttrs = &aesctrdrbgHWAttrs[CONFIG_AESCTRDRBG_0],
	},
};
const uint_least8_t AESCTRDRBG_count = CONFIG_TI_DRIVERS_AESCTRDRBG_COUNT;

static ECDHCC26X2_Object ecdhObjects[CONFIG_TI_DRIVERS_ECDH_COUNT];
static const ECDHCC26X2_HWAttrs ecdhHWAttrs[CONFIG_TI_DRIVERS_ECDH_COUNT] = {
	{
		.intPriority = TI_BLE_CRYPTO_INT_PRIORITY,
	},
};
const ECDH_Config ECDH_config[CONFIG_TI_DRIVERS_ECDH_COUNT] = {
	{
		.object = &ecdhObjects[CONFIG_ECDH_0],
		.hwAttrs = &ecdhHWAttrs[CONFIG_ECDH_0],
	},
};
const uint_least8_t ECDH_count = CONFIG_TI_DRIVERS_ECDH_COUNT;

static TRNGCC26XX_Object trngObjects[CONFIG_TI_DRIVERS_TRNG_COUNT];
static const TRNGCC26XX_HWAttrs trngHWAttrs[CONFIG_TI_DRIVERS_TRNG_COUNT] = {
	{
		.intPriority = TI_BLE_CRYPTO_INT_PRIORITY,
		.swiPriority = 0,
		.samplesPerCycle = 240000,
	},
};
const TRNG_Config TRNG_config[CONFIG_TI_DRIVERS_TRNG_COUNT] = {
	{
		.object = &trngObjects[CONFIG_TRNG_0],
		.hwAttrs = &trngHWAttrs[CONFIG_TRNG_0],
	},
};
const uint_least8_t TRNG_count = CONFIG_TI_DRIVERS_TRNG_COUNT;
